#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

pub fn rotate(a: &[i32], offset: usize) -> (out: Vec<i32>)
    ensures
        // Length is preserved.
        out.len() == a.len(),
        // Functional correctness: out[i] == a[(i + k) % n], with k = offset % n.
        forall|i: int|
            0 <= i && i < a.len() ==>
                out[i] == a[((i + (offset % a.len())) as int) % (a.len() as int)],
{
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n; // reduce offset to avoid overflow and unnecessary work
    let mut out = Vec::with_capacity(n);

    for i in 0..n
        invariant
            // Basic bounds facts.
            n > 0,
            k < n,
            // Progress/shape of output built so far.
            out.len() == i,
            out.len() <= n,
            // Contents correctness for all elements already pushed.
            forall|j: int|
                0 <= j && j < i ==>
                    out[j] == a[((j + (k as int)) % (n as int))],
    {
        out.push(a[(i + k) % n]);
    }

    out
}

} // verus!